window.TRANSLATIONS['de']['azkar.hub.type3_d'] = 'Tasbih, Tahmid, Takbir und überlieferte Gedenkformeln nach jedem Pflichtgebet.';
window.TRANSLATIONS['de']['azkar.hub.type4_t'] = 'Schlaf-Azkar';
