window.TRANSLATIONS['de']['azkar.hub.benefit4'] = 'Die Seele an das Gute erinnern und zum Gehorsam hinwenden.';
window.TRANSLATIONS['de']['azkar.hub.benefit5'] = 'Allah um Hilfe bitten und Tag und Nacht auf Ihn vertrauen.';
